let pos = 0;

function nextInt() {
  while (pos < data.length && data.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < data.length) {
    const c = data.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const M = nextInt();

const slope = new Float64Array(N + 1);
const intercept = new Float64Array(N + 1);

function add(bit, index, value) {
  for (let i = index; i <= N; i += i & -i) bit[i] += value;
}

function rangeAdd(bit, left, right, value) {
  add(bit, left, value);
  if (right < N) add(bit, right + 1, -value);
}

function prefixSum(bit, index) {
  let sum = 0;
  for (let i = index; i > 0; i -= i & -i) sum += bit[i];
  return sum;
}

const output = [];

for (let k = 0; k < M; k++) {
  const type = nextInt();
  const i = nextInt();

  if (type === 1) {
    const v = nextInt();
    const right = Math.min(N, i + v - 1);
    rangeAdd(slope, i, right, -1);
    rangeAdd(intercept, i, right, i + v);
